package com.ventas.security;
import com.ventas.controller.XmlTrialController;import com.ventas.service.*;import com.ventas.security.AuthModels.Identity;import com.ventas.dto.XmlTrialModels.*;import com.ventas.exception.ApiExceptionHandler;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(XmlTrialController.class) @ActiveProfiles("db") @Import({ApiSecurityConfig.class,SecurityConfig.class,ApiExceptionHandler.class}) class XmlTrialApiTest{
 @Autowired MockMvc mvc;@MockBean AuthService auth;@MockBean XmlTrialService service;void login(String...p){when(auth.authenticate(anyString(),anyString())).thenReturn(new Identity(1,"test","N","A","ADM",false,Set.of(p),UUID.randomUUID(),OffsetDateTime.now().plusHours(1)));}
 @Test void anonymousCannotReadLab()throws Exception{mvc.perform(get("/api/xml-pruebas/estado")).andExpect(status().isUnauthorized());}
 @Test void historyPermissionDoesNotGrantXmlDownloads()throws Exception{login("VEN.HISTORIAL");mvc.perform(post("/api/xml-pruebas/ejemplo/descarga").header("Authorization","Bearer test")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void downloadHasExplicitTrialHeaders()throws Exception{login("VEN.XML");when(service.downloadExample(any(),anyString(),eq("B"))).thenReturn(new Download("PRUEBA-SIN-VALIDEZ-B000-1.xml","<trial/>".getBytes(),"a".repeat(64)));mvc.perform(post("/api/xml-pruebas/ejemplo/descarga").header("Authorization","Bearer test")).andExpect(status().isOk()).andExpect(header().string("X-Document-Mode","LOCAL_SIN_FIRMA")).andExpect(header().string("Content-Disposition","attachment; filename=PRUEBA-SIN-VALIDEZ-B000-1.xml"));}
 @Test void noSendEndpointExists()throws Exception{login("VEN.XML");mvc.perform(post("/api/xml-pruebas/enviar").header("Authorization","Bearer test")).andExpect(status().isForbidden());verifyNoInteractions(service);}
}
